   if(!isset($allowed[$mime]))$error='Upload a JPG, PNG or WebP receipt image.';
   else{$name=bin2hex(random_bytes(18)).'.'.$allowed[$mime];$locations=[['dir'=>__DIR__.'/uploads/receipts','path'=>'uploads/receipts/'],['dir'=>__DIR__.'/includes/runtime/receipts','path'=>'includes/runtime/receipts/']];foreach($locations as $location){$dir=$location['dir'];if(!is_dir($dir)&&!@mkdir($dir,0775,true)&&!is_dir($dir))continue;if(!is_writable($dir))continue;$destination=$dir.DIRECTORY_SEPARATOR.$name;if(move_uploaded_file($tmp,$destination)){$receiptPath=$location['path'].$name;break;}}if($receiptPath===null){$receiptData=file_get_contents($tmp);if($receiptData===false||$receiptData==='')$error='The uploaded receipt could not be read. Please choose the image again.';else{$receiptPath='receipt-db/'.bin2hex(random_bytes(18));if(!store_receipt_blob($receiptPath,(string)$receiptMime,$receiptData))$error='The receipt image could not be stored. Please try again.';}}}
