const paymentForm=document.querySelector('.payment-card form');
if(paymentForm){
  paymentForm.enctype='multipart/form-data';
  const upload=document.createElement('div'); upload.className='receipt-upload';
  upload.innerHTML='<div class="receipt-upload-title"><span>🧾</span><div>Payment slip / receipt photo</div></div><label class="receipt-drop" for="receipt"><input id="receipt" type="file" name="receipt" accept="image/jpeg,image/png,image/webp" required><span class="receipt-choose">Choose payment slip</span><span class="receipt-name">No image selected</span></label><img class="receipt-preview" alt="Payment slip preview"><small>Upload a clear JPG, PNG or WebP image (maximum 5 MB).</small>';
  const receiptInput=upload.querySelector('#receipt'), drop=upload.querySelector('.receipt-drop'), name=upload.querySelector('.receipt-name'), preview=upload.querySelector('.receipt-preview');
  const showReceipt=()=>{const file=receiptInput.files[0];if(!file)return;name.textContent=file.name;preview.src=URL.createObjectURL(file);preview.style.display='block';};
  receiptInput.addEventListener('change',showReceipt);['dragenter','dragover'].forEach(event=>drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('dragover')}));['dragleave','drop'].forEach(event=>drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('dragover')}));
  const submit=paymentForm.querySelector('.payment-submit'); if(submit) paymentForm.insertBefore(upload,submit);
}

const revealItems=document.querySelectorAll('.reveal');
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});revealItems.forEach(item=>observer.observe(item));}else revealItems.forEach(item=>item.classList.add('visible'));
const account=document.querySelector('.account-number');
if(account){const copy=document.createElement('button');copy.type='button';copy.className='copy-account';copy.textContent='Copy';copy.setAttribute('aria-label','Copy bank account number');account.parentElement.append(copy);copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(account.textContent.trim());copy.textContent='Copied ✓';setTimeout(()=>copy.textContent='Copy',1800)}catch(e){copy.textContent='Select number';}})}
if(paymentForm){paymentForm.addEventListener('submit',()=>{const button=paymentForm.querySelector('.payment-submit');if(button&&paymentForm.checkValidity()){button.classList.add('loading');button.textContent='Submitting securely…'}})}
const hero=document.querySelector('#premiumHero'),priceBox=document.querySelector('#priceBox');
if(hero&&priceBox&&!matchMedia('(max-width:760px)').matches&&!matchMedia('(prefers-reduced-motion:reduce)').matches){hero.addEventListener('pointermove',event=>{const rect=hero.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width-.5,y=(event.clientY-rect.top)/rect.height-.5;priceBox.style.transform=`perspective(900px) rotateY(${(-4+x*7).toFixed(2)}deg) rotateX(${(-y*4).toFixed(2)}deg) translateY(-2px)`});hero.addEventListener('pointerleave',()=>priceBox.style.transform='')}</script>
